# one module per table; operations take and return record sets
class OrdersTableModule:
    def __init__(self, gateway):
        self.gateway = gateway
    def overdue(self, as_of):                 # -> record set of rows
        return self.gateway.select(where={"due <": as_of})
    def total(self, rows) -> Money:           # rule over the whole set
        return sum(row.total for row in rows)
    def flag_overdue(self, as_of) -> int:     # set-oriented write
        return self.gateway.update(set={"flagged": True}, where={"due <": as_of})
